// ===== ts/src/helpers/sdkdesc.ts (description) =====
type Scalar = string

type DescServerVar = {
  name: string
  required: boolean // the URL references it and it has no default
  dflt: string
}

type DescOption =
  | { name: 'apikey', env: string }
  | { name: 'secret', env: string }
  | { name: 'server', vars: { name: string, placeholder: string }[] }

// One member of an example request: a typed placeholder, or the id read off
// the record the example created.
type DescArg =
  | { name: string, type: Scalar, placeholder: string }
  | { name: string, fromCreated: string }

// The names the generated code gives the SDK as a whole, decided by the
// target's own naming functions (its Naming hook).
type DescLayout = {
  module: string // what an example imports the SDK by: a package, module path, header or namespace
  client: string // the client type
  ctor: string // the function or constructor an example creates a client with
}

// The names the generated code gives one entity, from the same hook.
type DescSymbols = {
  accessor: string // the client member, or function, that yields the entity
  var: string // a variable holding one entity
  vars: string // a variable holding a list of them
  module?: string // what an example must import to call its operations
  alias?: string // the name that import is bound to
  fields?: Record<string, string> // field -> the identifier a variable named after it takes
}

// A target's naming hook: the code generator's own naming functions, which may
// read the model. Exported as `Naming` by cmp/<target>/Naming_<target>.
type Naming = (model: any, target: any) => {
  layout: DescLayout
  symbols: (entity: any) => DescSymbols
}

type DescEntity = {
  name: string // model key, e.g. graph_ql
  Name: string // class-name stem, e.g. GraphQl
  sym: DescSymbols
  ops: string[] // generated, callable, canonical order
  id: string | null // the load-match id key
  dataId: string | null // the id on the returned record
  parents: string[] // required non-id load parameters of a nested entity
}

type DescQuick = {
  entity: string // the example entity (first active)
  list: DescArg[] | null // null: no list step
  load: { entity: string, args: DescArg[], nested: null | { parent: string, param: string } } | null
  create: DescArg[] | null
  update: DescArg[] | null
  patch: DescArg[] | null
  remove: DescArg[] | null
  chainsId: boolean // update/patch/remove take the id off the created record
  show: string[] // the fields a runtime that prints chosen fields prints: the record id, then one display field
}

type SdkDescription = {
  target: string
  name: string // model slug
  Name: string // class-name stem
  package: string // published package or module path of this target
  layout: DescLayout
  env: { prefix: string }
  auth: { active: boolean, in: string, name: string, basic: boolean, secret: boolean }
  options: DescOption[] // what the quick start's constructor passes, in order
  server: DescServerVar[] // variables the server URL references
  entities: DescEntity[]
  quick: DescQuick | null // null when no entity is active
}
// sdkDescription(model, target, naming?: Naming): SdkDescription  -- memoised per model and target; the calling component finds the hook:
// describeTarget(ctx$, target) in ts/src/cmp/ReadmeQuick.ts = sdkDescription(ctx$.model, target, optionalComponent(ctx$, target, 'Naming')?.Naming). OPTIONAL_COMPONENTS.Naming = null (no hook: genericNaming).

// ===== ts/src/helpers/example.ts (representation) =====
type Ent = { name: string, Name: string, sym: DescSymbols }

// A value an example names. `role` says what it holds, so a printer can
// choose its identifier: the entities a list returned, one of them, the one a
// load returned, the one a create returned.
type Ref = { role: 'many' | 'item' | 'one' | 'created', entity: Ent }

type Expr =
  | { k: 'lit', type: Scalar, text: string } // a typed literal; `text` when it is a string
  | { k: 'str', text: string } // a plain string
  | { k: 'env', name: string } // an environment variable, read
  | { k: 'record', of: Ref } // the record a returned entity holds
  | { k: 'field', of: Ref, field: string } // one field of that record
  | { k: 'fields', of: Ref, fields: string[] } // chosen fields of that record, for display
  | { k: 'map', entries: Entry[] }

type Entry = { key: string, value: Expr }

type Stmt =
  | { k: 'client', options: Entry[] } // construct the client; [] for none
  // `wide`: the argument is laid out one member per line where the language
  // lays maps out that way (a write's data; a load match of several members).
  | { k: 'call', entity: Ent, op: string, arg: Entry[] | null, bind: Ref | null, wide: boolean }
  | { k: 'each', item: Ref, of: Ref, body: Stmt[] }
  | { k: 'print', what: Expr }
  | { k: 'attempt', what: string, body: Stmt[] } // report a failure of `what`
  | { k: 'comment', text: string }
  | { k: 'gap' }

// A null arg on a call: the call takes no match. A create always takes data.
// Builders: clientBlock(desc), listBlock(desc, facts), loadBlock(desc, facts), writeBlock(desc, facts), writeOps(desc). Write results are never shown; `created` is bound only when desc.quick.chainsId. A print shows {k:'fields'} when facts.prints==='fields' and desc.quick.show is non-empty, else {k:'record'}.

// ===== runtime-fact table type (example.ts) =====
type ResultStyle =
  | 'throw' // the value is returned; a failure throws
  | 'raise' // the value is returned; a failure raises
  | 'pair' // (value, error)
  | 'errslot' // the value is returned, or a null value with an error slot set
  | 'union' // a result union whose success arm holds the value

type OpName = 'list' | 'load' | 'create' | 'update' | 'patch' | 'remove'

// What a target's runtime is, independently of any model: declared by the
// provider, checked against the runtime templates (test/runtimefacts.test.ts).
type RuntimeFacts = {
  method: Record<OpName, string> // the method each operation is in the runtime: load -> Load
  named: 'call' | 'bare' // prose names an operation as `load()` or as `load`
  async: boolean // operations resolve (a promise) rather than return
  result: ResultStyle
  collection: string // what a list's value is: 'array', '`[]any`', 'slice' (markdown)
  record: string // the code that reads an entity's record: '.data()'
  recordType?: string // the type that record is, where the runtime names one: 'dict'
  errVar?: string // pair, errslot: the variable a caller checks: 'err'
  errSlot?: string // errslot: what is set on failure: '*err'
  nullValue?: string // errslot: what a failed call returns: 'NULL'
  ok?: string // union: the success arm: '.ok'
  err?: string // union: the failure arm: '.err'
  prints: 'record' | 'fields' // how an example shows an entity: its whole record, or chosen fields
}
// The sentences for each ResultStyle live once in ts/src/helpers/runtimeprose.ts: listSentence(f), loadSentence(f), createComment(f), listComment(f, title), loadComment(f, title).

// ===== provider interface (example.ts) =====
// What a block uses, for a printer that declares imports.
type Uses = { env: boolean, field: boolean, print: boolean, entities: string[] }
// What one section's printing has declared so far; a printer that hoists a
// declaration (a handle, an error slot) records it here.
// `section` is every statement the section prints, known before its first
// block, for a printer that declares ahead what later blocks use.
type Scope = { declared: Set<string>, local: Set<string>, stmts: Stmt[], section: Stmt[] }

// Where a call stands: inside an attempt (whose handling covers it) or not,
// and whether it is the last statement of its block.
type CallContext = { inAttempt: boolean, last: boolean }

// One step of a section presented as one program: its title and its lines.
type ProgramStep = { title: string, lines: string[] }

type Syntax = {
  fence: string // the code fence language
  facts: RuntimeFacts
  // Each printer returns lines; `inner` prints nested statements at one more level.
  client: (s: Extract<Stmt, { k: 'client' }>, desc: SdkDescription, sc: Scope) => string[]
  call: (s: Extract<Stmt, { k: 'call' }>, desc: SdkDescription, sc: Scope, cx: CallContext) => string[]
  each: (s: Extract<Stmt, { k: 'each' }>, inner: (body: Stmt[]) => string[], sc: Scope) => string[]
  print: (s: Extract<Stmt, { k: 'print' }>, sc: Scope) => string[]
  attempt: (s: Extract<Stmt, { k: 'attempt' }>, inner: (body: Stmt[]) => string[], sc: Scope) => string[]
  comment: (text: string) => string
  expr: (e: Expr, sc: Scope) => string
  // Optional: lines a block needs ahead of its statements (a hoisted handle).
  before?: (stmts: Stmt[], desc: SdkDescription, sc: Scope) => string[]
  // Optional: the steps of a section assembled into one complete program, for
  // a language whose examples are whole programs that its README test runs.
  program?: (steps: ProgramStep[], desc: SdkDescription, sc: Scope) => string[]
}
// Printing helpers: printBlock(p, stmts, desc, sc); printSteps(p, steps, desc, sc) (one local scope across steps; a step's leading comment is printed before what `before` hoists); printProgram(p, steps, desc, sc) (fenced p.program(printSteps(...))); printJoined(p, steps, desc, sc) (steps in one block, blank line between). printStmts flattens any returned multi-line string into lines. A provider is `Syntax` exported by cmp/<t>/Syntax_<t>; its naming hook is `Naming` exported by cmp/<t>/Naming_<t>; both are found through optionalComponent. A target's own ReadmeQuick_<t> / ReadmeTopQuick_<t> still wins over its provider (packs, overrides).
